import{z as o,x as s,o as A,c as m,q as r,j as i,D as l,d as a,s as B,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"多语言评测","description":"","frontmatter":{"title":"多语言评测","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ml-multilingual-eval.md","filePath":"llm/ml-multilingual-eval.md","lastUpdated":1791413859000}'),D={name:"llm/ml-multilingual-eval.md"};function d(h,E,u,p,F,f){const t=s("Mermaid");return A(),m("div",null,[E[2]||(E[2]=r('<h1 id="多语言评测" tabindex="-1">多语言评测 <a class="header-anchor" href="#多语言评测" aria-label="Permalink to &quot;多语言评测&quot;">​</a></h1><div class="epigraph"><p>多语言评测的可信度不在题量，而在三件事：作答语言跟不跟得上提问语言、判卷人懂不懂这门语言、题在几种语言里各泄了多少。</p><footer>—— 据 Conneau 等，XNLI，2018；Hu 等，XTREME，2020；Shi 等，MGSM，ICLR 2023 与公开套件口径，按本课程整理</footer></div><p><a href="/llm/ml-low-resource">上一课</a>收在覆盖声明：没有原生卷的语言就写「未测」。<a href="/llm/multilingual-benchmarks">多语言基准</a>已经立了总纲——译文卷测迁移、原生卷测该语言世界的知识、禁止单标量平均。本课补操作层：把总纲落成一条可复现的评测流水线，处理回答语言一致性、判卷语言偏置、跨语言污染这些总纲之下最容易自欺的环节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多语言分数有三类隐性注水。第一类是回答语言不一致：用中文提问，模型用英文作答，判卷器恰好懂英文，分数照高——测到的不是中文能力而是英语能力。第二类是判卷偏置：LLM 判卷器自己就以英语为中心，对非英语答案的文风与正字法更严，同样的内容换语言打分系统性偏低；<a href="/llm/human-vs-auto-eval">人工评测 vs 自动评测</a>的原则在这里加倍成立——判卷者必须真正掌握该语言。第三类是跨语言污染：英文原题已在训练集里，译文卷继承了泄漏；原生题库与该语言维基百科高度重叠时泄漏更深。三类注水方向一致：把「英语能力外溢」或「背过答案」写成「多语言能力」。</p><h3 id="流水线上的检查点" tabindex="-1">流水线上的检查点 <a class="header-anchor" href="#流水线上的检查点" aria-label="Permalink to &quot;流水线上的检查点&quot;">​</a></h3><p>把三类问题各落成一个检查点。翻译质检：机译后做回译一致性检查，母语者抽检选项顺序、命名实体与题面自然度——生硬的译文测出的是翻译鲁棒性，不是目标语言能力。一致性指标：记录每题的提问语言、要求的作答语言、实际作答语言，回答语言匹配率单独成列发布。判卷校准：自动判卷的提示词用目标语言写并逐语言校准；人评招募该语言母语者，评分量表本地化。污染筛查：<a href="/llm/eval-contamination">训练-评测污染检测</a>的 n-gram 口径要加译本索引——同一题在不同语言里的表面形式完全不同，只查原文查不到。</p><p><span class="marginnote">回译检查翻译成大白话：把译文再机译回英语，跟原题对比，看意思是否走样。质检最常见的发现是细节走失——选项顺序被译者顺手调换、人名地名被转写成另一种惯用形式、题面从口语变成书面腔。这些改动单看译文毫无破绽，一对照原文才露出来，所以母语者抽检不能省。</span></p><p><span class="marginnote">MGSM 把 GSM8K 的 250 道小学数学题译成 10 种语言加英语成卷；其结果显示思维链语言选择能抬升低资源成绩——这也意味着判分时必须区分「解题语言」与「作答语言」，否则语言混杂会伪装成能力提升。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发布口径定成三张表。分语言分数表：每语言一列，附样本量与置信区间，小样本语言明确标注；不做跨语言平均，改报尾部最坏值。协议表：few-shot 例题语言、聊天模板是否本地化、判卷器版本、评测提示词语言，全部钉死——few-shot 例题用英语而题面用目标语，本身就是一种隐性迁移测试，要显式声明。污染表：各语言卷的泄漏筛查结果与排除规则。CMMLU 一类原生题库提供「该语言世界」的考点，与译文卷分列（见 <a href="/llm/mmlu">CMMLU</a>）。</p>',11)),(A(),i(n,null,{default:l(()=>[B(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EN%5B%22%E8%8B%B1%E6%96%87%E5%8E%9F%E5%8D%B7%22%5D%20--%3E%20TR%5B%22%E5%8F%97%E6%8E%A7%E7%BF%BB%E8%AF%91%E5%8D%B7%EF%BC%9A%E5%9B%9E%E8%AF%91%E6%A3%80%E6%9F%A5%22%5D%0A%20%20NAT%5B%22%E5%8E%9F%E7%94%9F%E9%A2%98%E5%BA%93%22%5D%20--%3E%20SCORE%5B%22%E5%88%86%E8%AF%AD%E8%A8%80%E5%88%86%E6%95%B0%E8%A1%A8%22%5D%0A%20%20TR%20--%3E%20CONS%5B%22%E4%BD%9C%E7%AD%94%E8%AF%AD%E8%A8%80%E4%B8%80%E8%87%B4%E6%80%A7%E6%8C%87%E6%A0%87%22%5D%0A%20%20CONS%20--%3E%20SCORE%0A%20%20JUDGE%5B%22%E5%88%A4%E5%8D%B7%E8%AF%AD%E8%A8%80%E6%A0%A1%E5%87%86%E4%B8%8E%E6%AF%8D%E8%AF%AD%E4%BA%BA%E8%AF%84%22%5D%20--%3E%20SCORE%0A%20%20CONT%5B%22%E8%AF%91%E6%9C%AC%E7%B4%A2%E5%BC%95%E6%B1%A1%E6%9F%93%E7%AD%9B%E6%9F%A5%22%5D%20--%3E%20SCORE%0A%20%20SCORE%20--%3E%20REPORT%5B%22%E5%8D%8F%E8%AE%AE%E8%A1%A8%E4%B8%8E%E6%B1%A1%E6%9F%93%E8%A1%A8%E9%9A%8F%E5%88%86%E6%95%B0%E5%8F%91%E5%B8%83%22%5D%0A"})]),fallback:l(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("三类注水共用一个机制：评测信号在语言边界上被偷换。回答语言不一致把目标语言理解偷换成英语生成；判卷偏置把语言质量差异偷换成能力差异；跨语言污染把记忆偷换成推理。三张表的作用是让偷换可检测：一致性指标暴露第一类，逐语言判卷校准与母语人评的差值暴露第二类，污染表暴露第三类。多语言评测多出的复杂度全在边界上：题面、作答、判卷、训练语料四个语言标签不重合时，分数必须按重合方式分列——这是"),e("a",{href:"/llm/tokenizer-fertility"},"分词 fertility 与公平"),a("「按语言分列」原则在评测端的对应物。")],-1)),(A(),i(n,null,{default:l(()=>[B(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%9B%9B%E4%B8%AA%E8%AF%AD%E8%A8%80%E6%A0%87%E7%AD%BE%E9%87%8D%E5%90%88%E5%90%97%EF%BC%9F%22%7D%20--%3E%20FULL%5B%22%E9%A2%98%E9%9D%A2%20%3D%20%E4%BD%9C%E7%AD%94%20%3D%20%E5%88%A4%E5%8D%B7%20%3D%20%E7%9B%AE%E6%A0%87%E8%AF%AD%E8%A8%80%22%5D%0A%20%20Q%20--%3E%20MIX%5B%22%E9%83%A8%E5%88%86%E9%87%8D%E5%90%88%22%5D%0A%20%20FULL%20--%3E%20OK%5B%22%E5%88%86%E6%95%B0%E5%8F%AF%E8%A7%A3%E8%AF%BB%E4%B8%BA%E7%9B%AE%E6%A0%87%E8%AF%AD%E8%A8%80%E8%83%BD%E5%8A%9B%22%5D%0A%20%20MIX%20--%3E%20D1%5B%22%E4%BD%9C%E7%AD%94%20%E2%89%A0%20%E9%A2%98%E9%9D%A2%EF%BC%9A%E6%B5%8B%E5%88%B0%E7%9A%84%E6%98%AF%E8%8B%B1%E8%AF%AD%E5%A4%96%E6%BA%A2%22%5D%0A%20%20MIX%20--%3E%20D2%5B%22%E5%88%A4%E5%8D%B7%20%E2%89%A0%20%E7%9B%AE%E6%A0%87%E8%AF%AD%E8%A8%80%EF%BC%9A%E5%88%A4%E5%8D%B7%E5%81%8F%E7%BD%AE%E6%B3%A8%E6%B0%B4%22%5D%0A%20%20MIX%20--%3E%20D3%5B%22%E8%AE%AD%E7%BB%83%E8%AF%AD%E6%96%99%E5%90%AB%E5%8E%9F%E9%A2%98%EF%BC%9A%E6%B1%A1%E6%9F%93%E6%B3%A8%E6%B0%B4%22%5D%0A%20%20D1%20--%3E%20SPLIT%5B%22%E6%8C%89%E9%87%8D%E5%90%88%E6%96%B9%E5%BC%8F%E5%88%86%E5%88%97%E6%8A%A5%E5%91%8A%22%5D%0A%20%20D2%20--%3E%20SPLIT%0A%20%20D3%20--%3E%20SPLIT%0A"})]),fallback:l(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">可以拿考试作弊类比四个标签：考卷（题面）、考生答题（作答）、阅卷人（判卷）、考前背过的资料（训练语料），各有各的语言。四个标签都是目标语言，考的才是这门语言；只要有一个标签被英语偷偷顶替——考生用英语答、阅卷人用英语批、答案考前背过——这个分数衡量的就不再是目标语言能力。初学者容易只盯分数高低，不去查标签错位。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>流水线解决不了覆盖问题：原生卷只能覆盖有限语种，其余语种保持「未测」，不用译文分冒充——这是<a href="/llm/ml-low-resource">低资源语言</a>留下的边界。译文卷测不出文化考点：选项里的本地法规、地名、历史语境翻不过来，那要等文化考点卷（<a href="/llm/ml-cultural-alignment">文化对齐</a>一课处理）。判卷校准也有限度：自动判卷器在低资源语言上本身的可靠性未经验证，此时唯一的裁判是人评，样本量与成本在协议表里如实报告。评测语言清单必须与产品声明覆盖的语言一一对应：多测是浪费，少测是虚报。</p><p><span class="marginnote">「未测」比「低分」诚实的原因：低分至少还可能来自判卷偏置或翻译走样，是测量工具的问题混着能力的问题；「未测」则明确告诉用户这一列没有尺子。这一步如果做错了——拿译文分冒充原生能力——后面产品的语言覆盖声明就整体失真，用户会拿着虚高的分数做技术选型。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三类注水：回答语言不一致、判卷语言偏置、跨语言污染；各配一个流水线检查点。</li><li>发布三张表：分语言分数（含尾部最坏值）、协议（few-shot 与判卷语言）、污染筛查。</li><li>判卷必须逐语言校准，人评用母语者；自动判卷在低资源语言上不能默认可信。</li><li>污染检测要含译本索引；MGSM 类套件要区分解题语言与作答语言。</li><li>覆盖声明止于已测语言；文化考点留给原生卷与文化考点卷。</li><li>出处：Conneau et al., XNLI, 2018；Hu et al., XTREME, ICML 2020；Shi et al., MGSM, ICLR 2023；Li et al., CMMLU, 2023；据<a href="/llm/multilingual-benchmarks">多语言基准</a>与<a href="/llm/human-vs-auto-eval">人工评测 vs 自动评测</a>口径整理。</li></ul>',6))])}const S=o(D,[["render",d]]);export{c as __pageData,S as default};
